      "content": "{\n  \"name\": \"dsh-wsl-llamacpp\",\n  \"version\": \"0.1.0\",\n  \"description\": \"DeepSeek Harness WSL plugin: llama.cpp / Unsloth Desktop OpenAI-compatible chat (status + completion).\",\n  \"license\": \"MIT\",\n  \"repository\": { \"type\": \"git\", \"url\": \"https://github.com/173787247/dsh-wsl-llamacpp.git\" },\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"engines\": { \"node\": \">=18\" },\n  \"scripts\": { \"test\": \"node --test test/*.test.js\" },\n  \"files\": [\"index.js\", \"lib\", \"cordis.patch.yml\", \"README.md\", \"README.en.md\", \"README.zh.md\", \"LICENSE\", \"CHANGELOG.md\"],\n  \"keywords\": [\"dsh-plugin\", \"wsl\", \"llama.cpp\", \"gguf\"],\n  \"dsh\": { \"bundle\": { \"patch\": \"./cordis.patch.yml\" } }\n}\n"
    },
